import React, { useState, useEffect } from "react";
import axios from "axios";
import "bootstrap/dist/css/bootstrap.min.css";
import { useParams } from "react-router-dom";
import live from "../../img/aulas-ao-vivo-coursifyme.jpg";
import private_api from "../../server/private_api";

const LecionaAula = () => {
  const { id } = useParams(); // Obter o ID do professor da URL
  const [materiais, setMateriais] = useState([]);
  const [cursos, setCursos] = useState([]);
  const [aulas, setAulas] = useState([]);
  const [cursoSelecionado, setCursoSelecionado] = useState("");
  const [novaAula, setNovaAula] = useState({
    titulo: "",
    arquivo: null,
  });
  const [carregando, setCarregando] = useState(true);

  // Carregar cursos do professor
  useEffect(() => {
    const carregarCursos = async () => {
      try {
        setCarregando(true);
        console.log("ID do professor:", id);

        // Substitui axios por private_api e atualiza o endpoint
        const response = await private_api.get (
          `/professores/${id}/listacursos`
        );

        console.log("Resposta da API:", response.data);

        // Adiciona verificação de tipo e estrutura dos dados
        if (response.data && Array.isArray(response.data)) {
          setCursos(response.data);
        } else {
          console.error("Formato de dados inesperado:", response.data);
          setCursos([]); // Garante que não seja undefined
        }
      } catch (error) {
        // Melhoria no tratamento de erros
        console.error(
          "Erro ao carregar cursos:",
          error.response?.data || error.message
        );
        setCursos([]); // Garante estado consistente em caso de erro
      } finally {
        setCarregando(false);
      }
    };

    // Adiciona verificação de ID antes de fazer a requisição
    if (id) {
      carregarCursos();
    } else {
      console.error("ID do professor não encontrado na URL");
      setCursos([]); // Limpa os cursos se não houver ID
    }
  }, [id]); // Mantém a dependência do ID

  // Carregar materiais e aulas quando um curso é selecionado
  useEffect(() => {
    if (cursoSelecionado) {
      const carregarDadosDoCurso = async () => {
        try {
          setCarregando(true);

          // Carregar materiais
          const materiaisRes = await axios.get(
            `/api/materiais/curso/${cursoSelecionado}`
          );
          setMateriais(materiaisRes.data);

          // Carregar aulas
          const aulasRes = await axios.get(
            `/api/aulas/curso/${cursoSelecionado}`
          );
          setAulas(aulasRes.data);
        } catch (error) {
          console.error("Erro ao carregar dados do curso:", error);
        } finally {
          setCarregando(false);
        }
      };

      carregarDadosDoCurso();
    } else {
      setMateriais([]);
      setAulas([]);
    }
  }, [cursoSelecionado]);

  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    if (!file || !cursoSelecionado) return;

    const formData = new FormData();
    formData.append("arquivo", file);
    formData.append("nome", file.name);
    formData.append("cursoId", cursoSelecionado);

    try {
      setCarregando(true);
      const response = await axios.post("/api/materiais", formData, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      });
      setMateriais([...materiais, response.data]);
      alert("Material adicionado com sucesso!");
    } catch (error) {
      console.error("Erro ao enviar arquivo:", error);
      alert("Erro ao enviar material");
    } finally {
      setCarregando(false);
    }
  };

  const removerMaterial = async (id) => {
    try {
      setCarregando(true);
      await axios.delete(`/api/materiais/${id}`);
      setMateriais(materiais.filter((material) => material.id !== id));
      alert("Material removido com sucesso!");
    } catch (error) {
      console.error("Erro ao remover material:", error);
      alert("Erro ao remover material");
    } finally {
      setCarregando(false);
    }
  };

  





  

  const removerAula = async (id) => {
    try {
      setCarregando(true);
      await axios.delete(`/api/aulas/${id}`);
      setAulas(aulas.filter((aula) => aula.id !== id));
      alert("Aula removida com sucesso!");
    } catch (error) {
      console.error("Erro ao remover aula:", error);
      alert("Erro ao remover aula");
    } finally {
      setCarregando(false);
    }
  };

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <nav className="nav nav-tabs mb-3 bg-white p-2 w-75 d-flex justify-content-center">
        <a className="nav-link" href="#">
          Cursos
        </a>
        <a className="nav-link active" href="#">
          Aulas
        </a>
        <a className="nav-link" href="#">
          Avaliações
        </a>
      </nav>

      <h2 className="mb-3 text-center">Aulas</h2>

      {carregando && cursos.length === 0 ? (
        <div className="text-center my-4">
          <div className="spinner-border text-primary" role="status">
            <span className="visually-hidden">Carregando...</span>
          </div>
        </div>
      ) : (
        <>
          <div className="d-flex justify-content-between w-75">
            <div>
              <h4>Aulas Ao Vivo</h4>
              <div className="card p-3">
                <img src={live} alt="Aula ao vivo" className="img-fluid" />
                <div className="d-flex justify-content-between mt-2">
                  <button className="btn btn-primary">Entrar</button>
                  <button className="btn btn-secondary">+ Nova Reunião</button>
                </div>
              </div>
            </div>
            <div>
              <div className="d-flex justify-content-between align-items-center mb-2">
                <h4>Aulas Gravadas</h4>
              </div>
              <div className="d-flex mb-2">
                <select
                  className="form-select me-2"
                  value={cursoSelecionado}
                  onChange={(e) => setCursoSelecionado(e.target.value)}
                  disabled={carregando}
                >
                  <option value="">Selecione o Curso</option>
                  {cursos.map((curso) => (
                    <option key={curso.id} value={curso.id}>
                      {curso.nome}
                    </option>
                  ))}
                </select>
              </div>

              {/* Formulário para adicionar nova aula */}
              {cursoSelecionado && (
                <div className="card p-3 mb-3">
                  <h5>Adicionar Nova Aula</h5>
                  <div className="mb-3">
                    <label className="form-label">Título da Aula</label>
                    <input
                      type="text"
                      className="form-control"
                      value={novaAula.titulo}
                      onChange={(e) =>
                        setNovaAula({ ...novaAula, titulo: e.target.value })
                      }
                      disabled={carregando}
                    />
                  </div>
                  <div className="mb-3">
                    <label className="form-label">Vídeo da Aula</label>
                    <input
                      type="file"
                      className="form-control"
                      accept="video/*"
                      onChange={(e) =>
                        setNovaAula({ ...novaAula, arquivo: e.target.files[0] })
                      }
                      disabled={carregando}
                    />
                  </div>
                  <button
                    className="btn btn-primary"
                    onClick={adicionarAula}
                    disabled={carregando}
                  >
                    {carregando ? "Enviando..." : "Enviar Aula"}
                  </button>
                </div>
              )}

              {carregando && cursoSelecionado ? (
                <div className="text-center my-4">
                  <div className="spinner-border text-primary" role="status">
                    <span className="visually-hidden">Carregando...</span>
                  </div>
                </div>
              ) : aulas.length > 0 ? (
                <table className="table table-bordered bg-white">
                  <tbody>
                    {aulas.map((aula) => (
                      <tr key={aula.id}>
                        <td>
                          <a
                            href={aula.videoUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                          >
                            {aula.titulo}
                          </a>
                        </td>
                        <td>
                          <button
                            className="btn btn-link"
                            disabled={carregando}
                          >
                            ✏️
                          </button>
                          <button
                            className="btn btn-link"
                            onClick={() => removerAula(aula.id)}
                            disabled={carregando}
                          >
                            🗑
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              ) : (
                <div className="alert alert-info">
                  {cursoSelecionado
                    ? "Nenhuma aula encontrada para este curso"
                    : "Selecione um curso para visualizar as aulas"}
                </div>
              )}
            </div>
          </div>

          {/* Seção de Materiais de Apoio */}
          <div className="mt-4 w-75">
            <h4>Material de Apoio</h4>
            <div className="card p-3">
              {cursoSelecionado ? (
                <>
                  <input
                    type="file"
                    className="form-control mb-3"
                    accept=".pdf,.doc,.docx,.ppt,.pptx"
                    onChange={handleFileUpload}
                    disabled={carregando}
                  />

                  {carregando ? (
                    <div className="text-center my-4">
                      <div
                        className="spinner-border text-primary"
                        role="status"
                      >
                        <span className="visually-hidden">Carregando...</span>
                      </div>
                    </div>
                  ) : materiais.length > 0 ? (
                    <ul className="list-group">
                      {materiais.map((material) => (
                        <li
                          key={material.id}
                          className="list-group-item d-flex justify-content-between align-items-center"
                        >
                          <a
                            href={material.arquivoUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                          >
                            {material.nome}
                          </a>
                          <div>
                            <button
                              className="btn btn-link"
                              disabled={carregando}
                            >
                              ✏️
                            </button>
                            <button
                              className="btn btn-link"
                              onClick={() => removerMaterial(material.id)}
                              disabled={carregando}
                            >
                              🗑
                            </button>
                          </div>
                        </li>
                      ))}
                    </ul>
                  ) : (
                    <div className="alert alert-info">
                      Nenhum material de apoio encontrado para este curso
                    </div>
                  )}
                </>
              ) : (
                <div className="alert alert-info">
                  Selecione um curso para visualizar os materiais de apoio
                </div>
              )}
            </div>
          </div>
        </>
      )}
    </div>
  );
};

export default LecionaAula;
